/**
 * SevenSegmentLCDStyles.ts — Seven-segment style library.
 *
 * This file is owned by the graphics team. It registers additional digit styles
 * on top of the three built-ins (classic, block, slim) that ship inside
 * SevenSegmentReadout.ts. To use these styles, import this module ONCE for its
 * side effects, before creating readouts:
 *
 *   import './SevenSegmentLCDStyles';
 *   new SevenSegmentReadout(el, { digits: 4, style: 'sws_test1' });
 *
 * Adding a new style: append another registerStyle(...) call. registerStyle
 * validates the markup (all of seg-a..seg-g and seg-dp must be present, no
 * id="..." attributes) and warns on duplicate names, so a bad export from a
 * graphics tool fails at registration instead of rendering a blank digit.
 * Removing a style: delete its registerStyle call (or the whole file / import).
 */
import { registerStyle, SEPARATOR_REGISTRY } from './SevenSegmentReadout';
// ± sign cell for 'sws_dash8_bold_italic' readouts (same cell size as a digit; the
// horizontal bar has the shape of that style's segment g, so '-' matches the style's own
// minus glyph). The sign is drawn 24.16 right of where a full digit is centered, which is
// how far a '1' (segments b and c) sits from the center of its cell: the distance from the
// center of the sign to the center of a leading '1' then equals the center-to-center
// distance of two full digits.
// Insert it before the digits with separators: [{ after: -1, type: 'sws_dash8_bold_italic_sign' }].
// Whole separator lit => '+'; dim seg-sign-v with setSeparatorPartOn() => '-'.
SEPARATOR_REGISTRY['sws_dash8_bold_italic_sign'] = {
    viewBox: '0 0 100 200',
    markup: `
  <polygon class="seg seg-sign-h" points="48.12 100.43 51.97 105.67 84.6 105.67 90.85 100.73 86.99 95.49 54.36 95.49 48.12 100.43"/>
  <path class="seg seg-sign-v" d="M75.47,78l3.67,5-2.65,10h-10l2.65-10,6.33-5ZM63.5,123.16l-3.67-5,2.65-10h10l-2.65,10-6.33,5Z"/>
  `,
};
